<script setup lang="ts">
import {ask} from './confirm';
import {ref,onMounted} from 'vue';import {api} from './api';import Dialog from './Dialog.vue';
const emit=defineEmits(['message']);const users=ref<any[]>([]),edit=ref<any>(null),reset=ref<any>(null),password=ref(''),busy=ref(false),error=ref('');
async function load(){try{users.value=await api('/admin/users')}catch(e:any){emit('message',e.message)}}onMounted(load);
async function save(){busy.value=true;error.value='';try{await api('/admin/users','POST',edit.value);edit.value=null;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function update(u:any,enabled:boolean,role:string){if(!await ask('确认更新用户权限或启用状态？该用户现有登录会话将撤销。'))return;try{await api('/admin/users/'+u.id,'PATCH',{enabled,role});await load()}catch(e:any){emit('message',e.message)}}
async function resetPassword(){busy.value=true;error.value='';try{await api('/admin/users/'+reset.value.id+'/reset-password','POST',{password:password.value});reset.value=null;password.value='';emit('message','密码已重置，原会话已撤销')}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><section><div class="section-title"><div><p class="eyebrow">IDENTITY & ACCESS</p><h1>用户管理</h1><p class="muted">管理员维护平台；普通用户通过项目成员关系获得访问权。</p></div><button class="primary" @click="edit={username:'',password:'',role:'member'};error=''">＋ 创建用户</button></div><div class="table-wrap"><table><thead><tr><th>用户名</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><strong>{{u.username}}</strong></td><td><select :value="u.role" aria-label="用户角色" @change="update(u,u.enabled,($event.target as HTMLSelectElement).value)"><option value="admin">管理员</option><option value="member">普通用户</option></select></td><td><span class="badge" :class="u.enabled?'online':'error'">{{u.enabled?'启用':'禁用'}}</span></td><td><div class="row"><button @click="reset=u;password='';error=''">重置密码</button><button @click="update(u,!u.enabled,u.role)">{{u.enabled?'禁用':'启用'}}</button></div></td></tr></tbody></table></div><Dialog v-if="edit" title="创建用户" @close="if(!busy)edit=null;"><form @submit.prevent="save"><label>用户名<input v-model="edit.username" required minlength="2" maxlength="64"></label><label>初始密码<input v-model="edit.password" type="password" autocomplete="new-password" required minlength="10"></label><label>角色<select v-model="edit.role"><option value="member">普通用户</option><option value="admin">管理员</option></select></label><p v-if="error" class="error-text" role="alert">{{error}}</p><footer class="form-actions"><button class="primary" :disabled="busy">创建用户</button></footer></form></Dialog><Dialog v-if="reset" :title="'重置 '+reset.username+' 的密码'" @close="if(!busy)reset=null;"><form @submit.prevent="resetPassword"><label>新密码<input v-model="password" type="password" required minlength="10" autocomplete="new-password"></label><p v-if="error" class="error-text" role="alert">{{error}}</p><footer class="form-actions"><button class="primary" :disabled="busy">重置密码并撤销会话</button></footer></form></Dialog></section></template>
